import {RESTRICTION_CATEGORIES, RESTRICTION_PARTS, escapeHTML as esc, powerPickCost, powerFamilyKey, selectedEntries, totals, validateDraft, parseRestrictionParts, formatRestrictionParts} from './lib/rules.mjs';
import {newDraft, normalizeDraft, makeCatalog, extendedCatalog, importItem, createFoundryItem, cleanText, normalizeSearch, safeImage, fileSlug, configSummary, randomId} from './lib/web-core.mjs';
import {icon, artifact} from './lib/icons.mjs';

const $=s=>document.querySelector(s);
const KEYS={draft:'iim-web:draft:v1',collection:'iim-web:collection:v1'};
const STEPS=[['Básico','A identidade do seu item','edit'],['Origem','De onde vem seu poder','spark'],['Restrições','O preço de uma lenda','lock'],['Poderes','Capacidades extraordinárias','bolt'],['Configuração','Cada detalhe importa','settings'],['Revisão','Pronto para a sua história','check']];
const GLYPHS=[['shield','Escudo'],['sword','Espada'],['hammer','Martelo'],['gem','Artefato'],['gauntlet','Manopla'],['bolt','Energia']];
const COLORS=['#d83343','#d18d32','#4f92bc','#768f76','#9473b7','#999da9'];
const state={view:'mancer',step:1,draft:newDraft(),document:null,id:null,base:null,catalog:null,collection:[],filter:{power:'',set:'',powerTab:'regular',onlySelected:false,origin:'',category:'access',collection:''},saveStatus:'Rascunho salvo neste navegador',parts:{}};
let toastTimer,saveTimer;
const t=value=>esc(cleanText(value));
const selected=(a,b)=>a===b?' selected':'';
const checked=value=>value?' checked':'';
const button=(label,action,cls='btn',glyph='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${glyph?icon(glyph):''}${label}</button>`;
const nameOf=p=>p.namePtBR||p.name;
const descOf=p=>p.effectPtBR||p.descriptionPtBR||p.description||'';
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function writeStore(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true;}catch{return false;}}
function toast(message,type='info'){clearTimeout(toastTimer);const el=$('#toast');el.className=`show ${type}`;el.replaceChildren();el.insertAdjacentHTML('beforeend',icon(type==='error'?'alert':'check'));el.append(document.createTextNode(message));toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
function autosave(){
 clearTimeout(saveTimer);state.saveStatus='Salvando rascunho…';updateSaveStatus();
 saveTimer=setTimeout(()=>{
  const ok=writeStore(KEYS.draft,{draft:state.draft,document:state.document,id:state.id,step:state.step});
  state.saveStatus=ok?'Rascunho salvo neste navegador':'Não foi possível salvar o rascunho';updateSaveStatus();
  if(!ok)toast('O armazenamento do navegador está cheio ou indisponível. Exporte seu item para guardar uma cópia.','error');
 },350);
}
function updateSaveStatus(){const el=$('#save-status');if(el)el.innerHTML=icon('check')+esc(state.saveStatus);}
function render(){
 const scrolls=[...document.querySelectorAll('[data-scroll]')].map(el=>[el.dataset.scroll,el.scrollTop]);
 document.querySelectorAll('.topnav a').forEach(el=>{el.classList.toggle('active',el.dataset.view===state.view);if(el.dataset.view===state.view)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
 $('#collection-count').textContent=state.collection.length;
 $('#main').innerHTML=state.view==='colecao'?collectionPage():state.view==='guia'?guidePage():builderPage();
 scrolls.forEach(([key,y])=>{const el=[...document.querySelectorAll('[data-scroll]')].find(el=>el.dataset.scroll===key);if(el)el.scrollTop=y;});
}
function pageIntro(eyebrow,title,description,actions='') {return `<div class="page-intro"><div><div class="eyebrow"><span></span>${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="intro-actions">${actions}</div></div>`;}
function builderPage(){
 return `<div class="page-wrap mmc-shell"><nav class="mmc-steps" aria-label="Etapas de criação">${STEPS.map(([label],i)=>`<button type="button" class="step-button mmc-step ${state.step===i+1?'active':''}" data-action="step" data-step="${i+1}" ${state.step===i+1?'aria-current="step"':''}>${i+1}. ${label}</button>`).join('')}</nav>
 <div class="workspace mmc-grid"><section class="editor mmc-card"><div class="editor-top"><span>Etapa ${state.step} de 6</span><span id="save-status">${icon('check')}${esc(state.saveStatus)}</span></div><div id="mobile-item-summary" class="mobile-item-summary">${mobileSummary()}</div><div class="step-content" id="step-content">${stepContent()}</div></section>
 <aside class="preview-column mmc-card" aria-label="Prévia do item"><div id="preview">${previewHTML()}</div><div class="preview-tip">${icon('info')}<p><b>Iconic não é Signature.</b> Um item icônico concede poderes ou efeitos especiais a quem o utiliza.</p></div><div class="catalog-stats"><span><b>${state.base.powers.length}</b> poderes</span><span><b>${state.base.origins.length}</b> origens</span><span><b>${state.base.specials.length}</b> especiais</span></div></aside></div>
 <footer class="editor-bottom mmc-nav"><div class="nav-back">${button('Voltar','previous','btn mmc-btn','',state.step===1?'disabled':'')}</div><div class="nav-center">${button('Importar JSON','import','btn mmc-btn')}</div><div class="nav-forward">${state.step<6?button('Seguinte','next','btn mmc-btn'):button('Salvar item','save','btn mmc-btn')}</div></footer></div>`;
}
function mobileSummary(){const v=totals(state.draft,state.catalog);return `<span>POWER VALUE <b>${v.powerValue}</b></span><small>${v.powerPicks} ${v.powerPicks===1?'pick':'picks'} − ${v.restrictionCount} ${v.restrictionCount===1?'restrição':'restrições'}</small>`;}
function sectionTitle(title,description){return `<div class="section-heading"><h2>${title}</h2><p>${description}</p></div>`;}
function input(label,path,type='text',placeholder='',extra=''){
 let v=state.draft;for(const key of path.split('.'))v=v?.[key];
 return `<label class="field"><span>${label}</span><input type="${type}" data-bind="${path}" value="${esc(v??'')}" placeholder="${esc(placeholder)}" ${extra}></label>`;
}
function selectInput(label,path,options){let v=state.draft;for(const key of path.split('.'))v=v?.[key];return `<label class="field"><span>${label}</span><select data-bind="${path}">${options.map(([key,label])=>`<option value="${esc(key)}"${selected(String(v),String(key))}>${esc(label)}</option>`).join('')}</select></label>`;}
function stepContent(){switch(state.step){case 1:return basicStep();case 2:return originStep();case 3:return restrictionsStep();case 4:return powersStep();case 5:return configStep();default:return reviewStep();}}
function basicStep(){return `${sectionTitle('Dê vida ao seu item.','Toda grande história tem um objeto que faz a diferença. Qual é o seu?')}
 ${input('Nome do item <span class="required">*</span>','name','text','Ex.: Égide Rubra','maxlength="120" autocomplete="off"')}
 <fieldset class="type-field"><legend>Tipo de item <span class="required">*</span></legend><div class="type-options">${[['weapon','Arma','Ataques e poderes associados','sword'],['item','Equipamento','Utilidade e poderes especiais','gauntlet']].map(([value,title,desc,glyph])=>`<label class="type-choice ${state.draft.itemType===value?'selected':''}"><input type="radio" name="item-type" data-bind="itemType" value="${value}"${checked(state.draft.itemType===value)} ${state.document?'disabled':''}>${icon(glyph)}<span><strong>${title}</strong><small>${desc}</small></span><span class="radio-indicator"></span></label>`).join('')}</div>${state.document?'<small class="field-help">O tipo do item importado é preservado.</small>':''}</fieldset>
 <label class="field"><span>Descrição e história <span class="optional">OPCIONAL</span></span><textarea data-bind="description" rows="4" maxlength="12000" placeholder="Quem o criou? Como funciona? O que o torna único?">${esc(state.draft.description)}</textarea></label>
 <div class="appearance-block"><div class="field-title">Símbolo do item <span class="optional">PRÉVIA</span></div><div class="glyph-options">${GLYPHS.map(([g,n])=>`<button class="glyph-option ${state.draft.visual.glyph===g?'selected':''}" data-action="glyph" data-glyph="${g}" aria-label="${n}" aria-pressed="${state.draft.visual.glyph===g}" title="${n}">${icon(g)}</button>`).join('')}<span class="appearance-divider"></span><div class="color-options" aria-label="Cor da prévia">${COLORS.map((c,i)=>`<button class="color-option ${c===state.draft.visual.color?'selected':''}" style="--swatch:${c}" data-action="color" data-color="${c}" aria-label="${['Vermelho','Dourado','Azul','Verde','Roxo','Prata'][i]}" aria-pressed="${c===state.draft.visual.color}">${c===state.draft.visual.color?icon('check'):''}</button>`).join('')}</div></div></div>
 <details class="image-details"><summary>${icon('upload')} Usar uma imagem personalizada <span>opcional</span></summary><div>${input('URL ou caminho da imagem no Foundry','image','text','https://… ou icons/…')}${button('Carregar imagem','image','btn btn-outline btn-small','upload')}<small>PNG, JPG, WebP ou GIF, até 1 MB. Uma imagem enviada fica incorporada no JSON.</small></div></details>
 <div class="note note-subtle">${icon('spark')}<p><b>A história vem primeiro.</b> Comece pelo conceito. Nas próximas etapas, você escolhe os poderes e define o preço dessa força.</p></div><button class="text-button mobile-examples" data-action="examples">Começar com um exemplo ${icon('arrow')}</button>`;}
function originStep(){const origin=state.catalog.origins.find(o=>o.uuid===state.draft.originUuid);return `${sectionTitle('Todo poder tem uma origem.','Escolha o que tornou esse objeto extraordinário. A origem pertence ao item.')}
 <div class="search-field">${icon('search')}<input id="origin-search" type="search" placeholder="Buscar origem…" value="${esc(state.filter.origin)}" aria-label="Buscar origem"></div><div class="results-line"><span id="origin-results">${state.catalog.origins.length} origens disponíveis</span><span>1 ESCOLHA</span></div>
 <div class="origin-list scroll-region" data-scroll="origins">${state.catalog.origins.map(o=>`<div class="origin-row ${o.uuid===state.draft.originUuid?'selected':''}" data-origin-row="${esc(normalizeSearch(o.name))}"><button class="origin-select" data-action="origin" data-uuid="${esc(o.uuid)}" aria-pressed="${o.uuid===state.draft.originUuid}"><span class="origin-symbol">${icon(originGlyph(o.name))}</span><span><strong>${t(o.name)}</strong><small>${t(o.description).slice(0,175)}${cleanText(o.description).length>175?'…':''}</small></span><span class="radio-indicator"></span></button><button class="info-button" data-action="origin-info" data-uuid="${esc(o.uuid)}" aria-label="Ler sobre ${esc(o.name)}">${icon('info')}</button></div>`).join('')}</div>
 <div class="note">${icon('info')}<p>${origin?`<b>${t(origin.name)}</b> selecionada. `:''}A origem do item não altera automaticamente a origem do personagem. Consulte o Narrador sobre Extraordinary Origin.</p></div>`;}
function originGlyph(name){return /tech|science|android/i.test(name)?'settings':/magic|mythic|spirit/i.test(name)?'gem':/mutant|symbiote/i.test(name)?'bolt':'spark';}
function restrictionParameters(def,record){
 const split=RESTRICTION_PARTS[def.id];
 if(split){const parts=state.parts[def.id]||parseRestrictionParts(def.id,record.value);return `<div class="restriction-params"><label><span>${esc(split.label)}</span><select data-part-id="${def.id}" data-part="attribute"><option value="">Selecionar…</option>${split.values.map(v=>`<option${selected(parts.attribute,v)}>${v}</option>`).join('')}</select></label><label><span>Valor mínimo</span><select data-part-id="${def.id}" data-part="threshold"><option value="">Valor…</option>${Array.from({length:split.max-split.min+1},(_,i)=>String(split.min+i)).map(v=>`<option${selected(parts.threshold,v)}>${v}</option>`).join('')}</select></label></div>`;}
 if(def.valueType==='number')return `<label class="field restriction-value"><span>Valor mínimo (${def.min}–${def.max})</span><select data-restriction-value="${def.id}"><option value="">Selecionar…</option>${Array.from({length:def.max-def.min+1},(_,i)=>String(i+def.min)).map(v=>`<option${selected(record.value,v)}>${v}</option>`).join('')}</select></label>`;
 const suggestions=restrictionSuggestions(def.id);return `<label class="field restriction-value"><span>Parâmetro da restrição</span><input data-restriction-value="${def.id}" value="${esc(record.value)}" placeholder="${esc(def.placeholderPtBR||'Descreva a condição…')}" ${suggestions.length?`list="suggest-${def.id}"`:''} maxlength="500">${suggestions.length?`<datalist id="suggest-${def.id}">${suggestions.map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist>`:''}</label>`;
}
function restrictionSuggestions(id){return ({'access-power':state.catalog.powers.map(p=>p.name),'access-origin':state.catalog.origins.map(p=>p.name),'access-movement':['Flight','Gliding','Leaping','Swingline','Burrowing','Wall-Crawling','Phasing','Teleport','Portal'],'access-size':['Tiny','Small','Average','Big','Huge'],'access-species':['Human','Mutant','Alien','Android','Asgardian','Atlantean'],'access-tag':['Worthy','Heroic','Menacing'],'access-team':['Avengers','X-Men','Fantastic Four','S.H.I.E.L.D.'],'access-trait':['Anathema','Berserker','Bloodthirsty','Breathe Different','Tech Reliance','Magic Reliance'],'challenging-weakness':['Fire','Cold','Electricity','Sonic','Magic','Mental'],'use-challenging-check':['Melee','Agility','Resilience','Vigilance','Ego','Logic']})[id]||[];}
function restrictionsStep(){const group=RESTRICTION_CATEGORIES.find(c=>c.id===state.filter.category)||RESTRICTION_CATEGORIES[0];return `${sectionTitle('Até lendas têm limites.','Cada restrição reduz o Power Value em 1. Escolha até três, de categorias diferentes; Óbvia permite múltiplas.')}
 <div class="restriction-meter"><span><b>${state.draft.restrictions.length}</b> / ${state.draft.narratorOverride?'∞':'3'} restrições escolhidas</span><label class="switch-label"><input type="checkbox" data-bind="narratorOverride"${checked(state.draft.narratorOverride)}><span class="switch"></span>Exceção do Narrador</label></div>
 <div class="category-tabs" role="group" aria-label="Categorias de restrição">${RESTRICTION_CATEGORIES.map(c=>{const count=state.draft.restrictions.filter(r=>state.catalog.restrictions.find(x=>x.id===r.id)?.category===c.id).length;return `<button class="${c.id===group.id?'active':''}" data-action="category" data-category="${c.id}" aria-pressed="${c.id===group.id}">${c.label}${count?`<b>${count}</b>`:''}</button>`;}).join('')}</div>
 <div class="results-line"><span>${group.label} <small>(${group.original})</small></span><span>${group.id==='obvious'?'MÚLTIPLAS ESCOLHAS':'1 POR CATEGORIA'}</span></div><div class="restriction-list scroll-region" data-scroll="restrictions-${group.id}">${state.catalog.restrictions.filter(r=>r.category===group.id).map(def=>{const record=state.draft.restrictions.find(r=>r.id===def.id);return `<article class="restriction-card ${record?'selected':''}"><label class="check-card"><input type="checkbox" data-restriction="${def.id}"${checked(!!record)}><span class="check-indicator">${icon('check')}</span><span><strong>${t(nameOf(def))}</strong><small>${t(descOf(def))}</small></span><span class="cost-badge negative">−1 PV</span></label>${record&&def.hasValue?restrictionParameters(def,record):''}</article>`;}).join('')}</div>
 ${state.draft.restrictions.length?`<div class="selected-restrictions"><span>SELECIONADAS</span>${state.draft.restrictions.map(r=>`<button class="chip" data-action="remove-restriction" data-id="${r.id}" title="Remover restrição">${t(nameOf(state.catalog.restrictions.find(d=>d.id===r.id)||r))}${icon('close')}</button>`).join('')}</div>`:''}`;}
function powersStep(){const regular=state.filter.powerTab==='regular',selection=selectedEntries(state.draft,state.catalog),powerSets=[...new Set(state.catalog.powers.map(p=>p.powerSet))].sort();return `${sectionTitle('Escolha o extraordinário.','Combine poderes do D616 com propriedades exclusivas de Iconic Items.')}
 <div class="power-tabs" role="group" aria-label="Tipos de poderes"><button data-action="power-tab" data-tab="regular" class="${regular?'active':''}" aria-pressed="${regular}">Poderes regulares <span>${state.catalog.powers.length}</span></button><button data-action="power-tab" data-tab="special" class="${!regular?'active':''}" aria-pressed="${!regular}">Especiais <span>${state.catalog.specials.length}</span></button></div>
 <div class="power-tools"><div class="search-field">${icon('search')}<input id="power-search" type="search" value="${esc(state.filter.power)}" placeholder="Buscar poder, efeito ou conjunto…" aria-label="Buscar poderes"></div>${regular?`<select id="power-set" aria-label="Conjunto de poderes"><option value="">Todos os conjuntos</option>${powerSets.map(s=>`<option${selected(state.filter.set,s)}>${esc(s)}</option>`).join('')}</select>`:''}</div>
 <div class="results-line"><span id="power-results"></span><label class="only-selected"><input id="only-selected" type="checkbox"${checked(state.filter.onlySelected)}>Só selecionados</label></div>
 ${!regular&&state.draft.itemType==='weapon'?'<div class="weapon-auto">'+icon('sword')+'<span><b>Weapon</b> incluído automaticamente por ser uma arma.</span><b>1 pick</b></div>':''}
 <div class="power-grid scroll-region" data-scroll="powers-${regular?'regular':'special'}">${(regular?state.catalog.powers:state.catalog.specials.filter(s=>s.id!=='weapon')).map(p=>{const isSelected=regular?state.draft.regularPowerUuids.includes(p.uuid):state.draft.specialPowerIds.includes(p.id),id=regular?p.uuid:p.id,cost=regular?powerPickCost(p):1;return `<article class="power-card ${isSelected?'selected':''}" data-power-row data-search="${esc(normalizeSearch(`${p.name} ${p.namePtBR||''} ${p.powerSet||''} ${descOf(p)} ${p.prerequisites||''}`))}" data-set="${esc(p.powerSet||'')}" data-selected="${isSelected}"><label><input type="checkbox" ${regular?'data-power':'data-special'}="${esc(id)}"${checked(isSelected)}><span class="check-indicator">${icon('check')}</span><span class="power-card-main"><strong>${t(regular?p.name:nameOf(p))}</strong><small>${regular?t(p.powerSet):t(descOf(p)).slice(0,130)}</small></span></label><div class="power-card-bottom"><span class="cost-badge">${cost} ${cost===1?'pick':'picks'}</span><button class="info-button" data-action="power-info" data-kind="${regular?'regular':'special'}" data-id="${esc(id)}" aria-label="Detalhes de ${esc(p.name)}">${icon('info')}<span>Detalhes</span></button></div></article>`;}).join('')}<div class="filter-empty" id="power-empty" hidden>${icon('search')}<h3>Nenhum poder encontrado.</h3><p>Tente outro termo ou conjunto.</p></div></div>
 <div class="power-picks-summary"><span>${icon('bolt')}<b>${selection.powers.length+selection.specials.length}</b> poderes / propriedades</span><span><b>${totals(state.draft,state.catalog).powerPicks}</b> Power Picks</span></div>`;}
function configStep(){const d=state.draft,s=selectedEntries(d,state.catalog);let html=sectionTitle('Ajuste cada detalhe.','Defina como o item funciona e configure as propriedades que você escolheu.');
 if(d.itemType==='weapon')html+=`<section class="config-card"><div class="config-title">${icon('sword')}<h3>Configuração da arma</h3></div><div class="form-grid two">${selectInput('Modo inicial','weaponDetails.primaryMode',[['mle','Melee — corpo a corpo'],['agl','Agility — à distância']])}${selectInput('Tipo de dano','weaponDetails.damageType',[['health','Health'],['focus','Focus']])}</div><div class="weapon-modes"><div><span class="mode-title">MELEE</span>${input('Alcance','weaponDetails.meleeRange','text','Reach')}${input('Bônus no multiplicador','weaponDetails.meleeDamageMultiplierBonus','number','0','step="1"')}</div><div><span class="mode-title">AGILITY</span>${input('Alcance (espaços)','weaponDetails.agilityRange','text','5')}${input('Bônus no multiplicador','weaponDetails.agilityDamageMultiplierBonus','number','0','step="1"')}</div></div></section>`;
 for(const p of s.specials){let content='';if(['reduced-focus','stackable'].includes(p.id)){const options=s.powers.filter(x=>p.id!=='stackable'||x.numbered>0).map(p=>[p.uuid,p.name]);content=selectInput('Poder afetado',`specialConfig.${p.id==='stackable'?'stackableTarget':'reducedFocusTarget'}`,[['','Selecionar poder…'],...options]);}if(p.id==='effect-options')content=input('Efeitos disponíveis','specialConfig.effectOptions','text','Ex.: Fire, Electricity, Cold');if(p.id==='damage-switch')content=selectInput('Dano alternativo','specialConfig.damageSwitch',[['focus','Focus'],['health','Health']]);if(p.id==='negatite')content=selectInput('Modo inicial','specialConfig.negatiteMode',[['penetration','Ignorar 10 de proteção'],['damage','+1 no multiplicador Health']]);if(content)html+=`<section class="config-card"><div class="config-title">${icon('spark')}<h3>${t(nameOf(p))}</h3></div><p class="config-help">${t(descOf(p))}</p>${content}</section>`;}
 html+=`<section class="config-card"><div class="config-title">${icon('lock')}<h3>Iconic Reliance <span>OPCIONAL</span></h3></div><p class="config-help">Registre se os poderes do portador dependem desse item.</p>${selectInput('Dependência','reliance.type',[['none','Nenhuma'],['tech','Tech Reliance'],['magic','Magic Item Reliance']])}${d.reliance.type!=='none'?input('Poderes afetados','reliance.affected','text','Definir com o Narrador'):''}</section><div class="note note-subtle">${icon('info')}<p>As regras e os efeitos do item serão incluídos no JSON. As automações em jogo dependem do sistema e do módulo instalados no Foundry.</p></div>`;return html;
}
function reviewStep(){const s=selectedEntries(state.draft,state.catalog),v=validateDraft(state.draft,state.catalog);return `${sectionTitle('Sua lenda está pronta.','Confira os detalhes, salve na sua coleção e leve seu item para a mesa.')}
 ${v.errors.length?`<div class="validation-errors" role="alert"><b>${icon('alert')}Falta pouco para concluir</b><ul>${v.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:`<div class="ready-banner">${icon('check')}Tudo certo. Seu item está pronto para ser exportado.</div>`}
 ${v.warnings.length?`<div class="validation-warnings"><b>Para revisar com o Narrador</b><ul>${v.warnings.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}
 <article class="review-sheet" id="print-sheet"><div class="review-sheet-head"><div><span class="eyebrow">${state.draft.itemType==='weapon'?'ARMA ICÔNICA':'EQUIPAMENTO ICÔNICO'}</span><h3>${esc(state.draft.name||'Item sem nome')}</h3><p>${t(s.origin?.name||'Origem não definida')}</p></div><div class="review-pv"><span>POWER VALUE</span><strong>${totals(state.draft,state.catalog).powerValue}</strong></div></div>${state.draft.description?`<p class="item-story">${esc(state.draft.description).replaceAll('\n','<br>')}</p>`:''}<div class="review-section"><h4>PODERES REGULARES <span>${s.powers.length}</span></h4>${s.powers.length?s.powers.map(p=>`<div class="review-row"><span><b>${t(p.name)}</b><small>${t(p.powerSet)}</small></span><span>${powerPickCost(p)} picks</span></div>`).join(''):'<p class="muted">Nenhum poder regular selecionado.</p>'}</div><div class="review-section"><h4>PROPRIEDADES ESPECIAIS <span>${s.specials.length}</span></h4>${s.specials.map(p=>`<div class="review-property"><b>${t(nameOf(p))}</b>${configSummary(p,state.draft,state.catalog)?`<span>${t(configSummary(p,state.draft,state.catalog))}</span>`:''}<p>${t(descOf(p))}</p></div>`).join('')||'<p class="muted">Nenhuma propriedade.</p>'}</div><div class="review-section"><h4>RESTRIÇÕES <span>${s.restrictions.length}</span></h4>${s.restrictions.map(r=>`<div class="review-property"><b>${t(nameOf(r))}</b>${r.value?`<span>${esc(r.value)}</span>`:''}<p>${t(descOf(r))}</p></div>`).join('')||'<p class="muted">Nenhuma restrição.</p>'}</div>${state.draft.itemType==='weapon'?`<div class="review-section"><h4>CONFIGURAÇÃO DA ARMA</h4><p>Modo: <b>${state.draft.weaponDetails.primaryMode==='agl'?'Agility':'Melee'}</b> · Dano: <b>${state.draft.weaponDetails.damageType==='focus'?'Focus':'Health'}</b></p><p>Melee: ${esc(state.draft.weaponDetails.meleeRange)} / DM +${esc(state.draft.weaponDetails.meleeDamageMultiplierBonus)}<br>Agility: ${esc(state.draft.weaponDetails.agilityRange)} / DM +${esc(state.draft.weaponDetails.agilityDamageMultiplierBonus)}</p></div>`:''}${state.draft.reliance.type!=='none'?`<div class="review-section"><h4>ICONIC RELIANCE</h4><p>${state.draft.reliance.type==='tech'?'Tech Reliance':'Magic Item Reliance'}: ${esc(state.draft.reliance.affected||'Conforme o Narrador')}</p></div>`:''}<div class="review-total">${totals(state.draft,state.catalog).powerPicks} Power Picks − ${s.restrictions.length} restrições <b>Power Value ${totals(state.draft,state.catalog).powerValue}</b></div></article>
 <div class="export-actions">${button('Exportar para Foundry','export','btn btn-red','download',v.errors.length?'disabled':'')}${button('Imprimir / PDF','print','btn btn-outline','print',v.errors.length?'disabled':'')}</div><p class="export-caption">No Foundry: crie um Item, clique com o botão direito e escolha <b>Importar dados</b>. Importe o JSON baixado.</p>`;}
function previewHTML(){const d=state.draft,s=selectedEntries(d,state.catalog),v=totals(d,state.catalog);return `<div class="preview-heading"><span>PRÉVIA DO ITEM</span><span class="live-indicator"><i></i>AO VIVO</span></div><article class="item-preview" style="--accent:${d.visual.color}"><div class="item-card-top"><span>ICONIC ITEM</span>${icon(d.itemType==='weapon'?'sword':'gauntlet')}</div><div class="artifact-stage"><span class="artifact-coordinate coord-left">D616 / IIM</span><span class="artifact-coordinate coord-right">${d.itemType==='weapon'?'WEAPON':'GEAR'}</span><div class="stage-ring"></div>${safeImage(d.image)&&/^https?:|^data:/i.test(d.image)?`<img class="custom-artifact" src="${esc(d.image)}" alt="Imagem do item" referrerpolicy="no-referrer" data-preview-image>${artifact(d.visual.glyph)}`:artifact(d.visual.glyph)}</div><div class="item-card-info"><span class="item-type">${d.itemType==='weapon'?'ARMA ICÔNICA':'EQUIPAMENTO ICÔNICO'}</span><h3>${esc(d.name||'Seu próximo ícone')}</h3><p>${t(s.origin?.name||'Uma origem a descobrir')}</p></div><div class="item-power-value"><div><span>POWER VALUE</span><small>${v.powerPicks} ${v.powerPicks===1?'pick':'picks'} − ${v.restrictionCount} ${v.restrictionCount===1?'restrição':'restrições'}</small></div><strong>${v.powerValue}<span>PV</span></strong></div><div class="item-card-code"><span>MULTIVERSE D616</span><span class="barcode" aria-hidden="true"></span></div></article><div class="selection-preview"><div><span>PODERES</span><b>${s.powers.length+s.specials.length}</b></div><div><span>RESTRIÇÕES</span><b>${s.restrictions.length}<small> / ${d.narratorOverride?'∞':'3'}</small></b></div></div><div class="preview-progress"><div><span>SUA CRIAÇÃO</span><b>${state.step} de 6 etapas</b></div><span><i style="width:${state.step/6*100}%"></i></span></div>`;}
function updatePreview(){if($('#preview'))$('#preview').innerHTML=previewHTML();if($('#mobile-item-summary'))$('#mobile-item-summary').innerHTML=mobileSummary();}
function filterPowers(){let count=0;const q=normalizeSearch(state.filter.power);document.querySelectorAll('[data-power-row]').forEach(el=>{const show=(!q||el.dataset.search.includes(q))&&(state.filter.powerTab!=='regular'||!state.filter.set||el.dataset.set===state.filter.set)&&(!state.filter.onlySelected||el.dataset.selected==='true');el.hidden=!show;if(show)count++;});if($('#power-results'))$('#power-results').textContent=`${count} ${count===1?'poder disponível':'poderes disponíveis'}`;if($('#power-empty'))$('#power-empty').hidden=count>0;}
function filterOrigins(){const q=normalizeSearch(state.filter.origin);let count=0;document.querySelectorAll('[data-origin-row]').forEach(el=>{el.hidden=!!q&&!el.dataset.originRow.includes(q);if(!el.hidden)count++;});if($('#origin-results'))$('#origin-results').textContent=`${count} ${count===1?'origem disponível':'origens disponíveis'}`;}
function afterRender(){if(state.view==='mancer'&&state.step===4)filterPowers();if(state.view==='mancer'&&state.step===2)filterOrigins();if(state.view==='colecao')filterCollection();}
const fullRender=()=>{render();afterRender();};
function collectionPage(){return `<div class="page-wrap collection-wrap">${pageIntro('O SEU ARSENAL','Itens com uma história para contar.','Seus itens ficam salvos neste navegador. Exporte um JSON para guardar uma cópia.',button('Criar novo item','new','btn btn-red','plus'))}<div class="collection-toolbar"><div class="search-field">${icon('search')}<input type="search" id="collection-search" value="${esc(state.filter.collection)}" placeholder="Buscar na sua coleção…" aria-label="Buscar na coleção"></div><span>${state.collection.length} ${state.collection.length===1?'item salvo':'itens salvos'}</span></div>${state.collection.length?`<div class="collection-grid">${state.collection.map(item=>{const d=item.document,f=d.flags['iconic-item-mancer'],visual=d.flags['iconic-item-mancer-web']?.visual||newDraft().visual;return `<article class="collection-card" data-collection-row="${esc(normalizeSearch(`${d.name} ${f.origin?.name||''}`))}" style="--accent:${/^#[0-9a-f]{6}$/i.test(visual.color)?visual.color:'#d83343'}"><div class="collection-art">${artifact(visual.glyph)}<span class="collection-pv">${Number(f.powerValue)||1}<small>PV</small></span></div><div class="collection-card-body"><span class="eyebrow">${d.type==='weapon'?'ARMA ICÔNICA':'EQUIPAMENTO ICÔNICO'}</span><h2>${esc(d.name)}</h2><p>${t(f.origin?.name||'')}</p><small>${f.powerPicks} Power Picks · ${f.restrictions?.length||0} restrições</small><div class="collection-card-actions">${button('Abrir','open-item','btn btn-dark btn-small','edit',`data-id="${esc(item.id)}"`)}${button('','export-item','icon-btn','download',`data-id="${esc(item.id)}" aria-label="Exportar ${esc(d.name)}" title="Exportar JSON"`)}${button('','duplicate-item','icon-btn','copy',`data-id="${esc(item.id)}" aria-label="Duplicar ${esc(d.name)}" title="Duplicar"`)}${button('','delete-item','icon-btn delete','trash',`data-id="${esc(item.id)}" aria-label="Excluir ${esc(d.name)}" title="Excluir"`)}</div></div></article>`;}).join('')}</div><div id="collection-empty" class="empty-state" hidden>${icon('search')}<h2>Nenhum item encontrado.</h2><p>Tente outro nome ou origem.</p></div>`:`<div class="empty-state">${icon('gem')}<span class="eyebrow">SUA COLEÇÃO COMEÇA AQUI</span><h2>O próximo item lendário pode ser seu.</h2><p>Crie um item no Mancer ou importe um JSON que você já tem.</p><div>${button('Criar meu primeiro item','new','btn btn-red','plus')}${button('Importar JSON','import','btn btn-outline','upload')}</div></div>`}</div>`;}
function filterCollection(){const q=normalizeSearch(state.filter.collection);let count=0;document.querySelectorAll('[data-collection-row]').forEach(el=>{el.hidden=!!q&&!el.dataset.collectionRow.includes(q);if(!el.hidden)count++;});if($('#collection-empty'))$('#collection-empty').hidden=count>0;}
function guidePage(){return `<div class="page-wrap guide-wrap">${pageIntro('DO CONCEITO À SUA MESA','Um item icônico em seis passos.','O mesmo Mancer do Foundry, agora no seu navegador.',button('Abrir o Mancer','go-mancer','btn btn-red','arrow'))}<div class="guide-layout"><div><section class="guide-card"><span class="eyebrow">01 / CRIE</span><h2>Da ideia ao extraordinário.</h2><p>Defina nome e tipo, escolha uma origem, equilibre as restrições e selecione os poderes. Depois, configure o funcionamento e revise o resultado.</p><div class="guide-steps">${STEPS.map(([n,s,g],i)=>`<div><span>${icon(g)}</span><p><b>${i+1}. ${n}</b><small>${s}</small></p></div>`).join('')}</div></section><section class="guide-card"><span class="eyebrow">02 / EQUILIBRE</span><h2>Entenda o Power Value.</h2><div class="formula">Power Value <span>=</span> Power Picks <span>−</span> Restrições</div><p>O resultado é sempre no mínimo <b>1</b>. Um poder regular custa 1 pick; poderes numerados custam o seu nível. Cada propriedade especial custa 1 pick. Armas recebem <b>Weapon</b> automaticamente.</p><p>São permitidas até três restrições sem exceção do Narrador. Apenas <b>Óbvia (Obvious)</b> aceita várias restrições da mesma categoria. <b>Constructable</b> não combina com restrições <b>Unattached</b>.</p></section><section class="guide-card"><span class="eyebrow">03 / LEVE PARA O FOUNDRY</span><h2>Sua próxima sessão começa aqui.</h2><ol class="guide-list"><li>Na etapa Revisão, clique em <b>Exportar para Foundry</b>.</li><li>No mundo com o sistema <b>Multiverse D616 v0.2.99+</b>, abra o diretório <b>Itens</b> e crie um Item do mesmo tipo: Arma ou Equipamento.</li><li>Clique com o botão direito no item do diretório e selecione <b>Importar dados</b>. Escolha o JSON baixado.</li><li>Adicione o item ao inventário. Os poderes estarão associados ao próprio equipamento.</li></ol><p>Use o módulo <b>Iconic Item Mancer v2.0.8+</b> para editar no Mancer, controlar itens vestidos e acessar suas automações. Poderes sem automação continuam disponíveis para consulta e aplicação pelo Narrador.</p></section></div><aside><section class="guide-side"><span class="guide-symbol">${icon('save')}</span><h3>Seus itens, com você.</h3><p>O rascunho e a coleção são salvos neste navegador. Não há conta ou sincronização entre dispositivos.</p><p>Exporte os JSONs para backup. Você pode importá-los novamente no site e continuar editando.</p></section><section class="guide-side"><span class="guide-symbol">${icon('book')}</span><h3>Feito para o D616.</h3><p>Baseado no módulo v2.0.8 e nos catálogos do Charactermancer do sistema v0.2.99.</p><p>398 poderes, 40 origens, 39 restrições e 30 propriedades especiais.</p><a href="https://github.com/rodrigosinistro/iconic-item-mancer" target="_blank" rel="noopener noreferrer">Ver o projeto ${icon('arrow')}</a></section></aside></div></div>`;}
function modal(title,body,footer=''){const el=$('#modal');el.innerHTML=`<div class="modal-head"><div><span class="eyebrow">ICONIC ITEM MANCER</span><h2 id="modal-title">${esc(title)}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!el.open)el.showModal();}
function confirmAction(title,body,action,extra=''){modal(title,`<p>${esc(body)}</p>`,button('Cancelar','close-modal','btn btn-outline')+button('Confirmar',action,'btn btn-red','',extra));}
function setStep(step,validate=false){if(validate){const errors=validateDraft(state.draft,state.catalog).errors;let relevant=[];if(state.step===1&&!state.draft.name.trim())relevant=['Informe o nome do item.'];if(state.step===2&&!state.draft.originUuid)relevant=['Escolha a origem do item.'];if(state.step===3)relevant=errors.filter(e=>/restriç|categoria|parâmetro|Valor inválido|Constructable/i.test(e));if(state.step===4)relevant=errors.filter(e=>/pelo menos/i.test(e));if(state.step===5)relevant=errors.filter(e=>/precisa indicar|bônus de dano/i.test(e));if(relevant.length){toast(relevant[0],'error');return;}}state.step=Math.max(1,Math.min(6,step));autosave();fullRender();$('#step-content')?.scrollIntoView({block:'nearest',behavior:'smooth'});}
function toggleRestriction(id,on){const def=state.catalog.restrictions.find(d=>d.id===id);if(!def)return;if(!on){state.draft.restrictions=state.draft.restrictions.filter(r=>r.id!==id);delete state.parts[id];}else{if(def.category==='unattached'&&state.draft.specialPowerIds.includes('constructable')){toast('Constructable é incompatível com restrições Unattached.','error');fullRender();return;}const other=state.draft.restrictions.filter(r=>state.catalog.restrictions.find(d=>d.id===r.id)?.category===def.category);const replacing=def.category!=='obvious'&&other.length;if(!state.draft.narratorOverride&&state.draft.restrictions.length>=3&&!replacing){toast('O limite é de três restrições. Ative a exceção do Narrador para permitir mais.','error');fullRender();return;}if(replacing){state.draft.restrictions=state.draft.restrictions.filter(r=>!other.includes(r));for(const r of other)delete state.parts[r.id];}state.draft.restrictions.push({id,value:''});}autosave();fullRender();}
function togglePower(uuid,on){const p=state.catalog.powers.find(p=>p.uuid===uuid);if(!p)return;let list=state.draft.regularPowerUuids.filter(u=>u!==uuid);if(on){list=list.filter(u=>{const existing=state.catalog.powers.find(p=>p.uuid===u);return !existing||!existing.numbered||!p.numbered||powerFamilyKey(existing)!==powerFamilyKey(p);});list.push(uuid);}state.draft.regularPowerUuids=list;for(const key of ['stackableTarget','reducedFocusTarget'])if(!list.includes(state.draft.specialConfig[key]))state.draft.specialConfig[key]='';autosave();fullRender();}
function toggleSpecial(id,on){if(id==='constructable'&&on&&state.draft.restrictions.some(r=>state.catalog.restrictions.find(d=>d.id===r.id)?.category==='unattached')){toast('Constructable é incompatível com restrições Unattached.','error');fullRender();return;}state.draft.specialPowerIds=state.draft.specialPowerIds.filter(s=>s!==id);if(on)state.draft.specialPowerIds.push(id);autosave();fullRender();}
function bindField(el){const path=el.dataset.bind;if(!path)return;const allowed=new Set(['name','description','image','itemType','originUuid','narratorOverride','specialConfig.damageSwitch','specialConfig.effectOptions','specialConfig.negatiteMode','specialConfig.reducedFocusTarget','specialConfig.stackableTarget','reliance.type','reliance.affected','weaponDetails.primaryMode','weaponDetails.damageType','weaponDetails.meleeRange','weaponDetails.agilityRange','weaponDetails.meleeDamageMultiplierBonus','weaponDetails.agilityDamageMultiplierBonus']);if(!allowed.has(path))return;let target=state.draft;const parts=path.split('.');for(const key of parts.slice(0,-1))target=target[key];target[parts.at(-1)]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(path==='weaponDetails.primaryMode')state.draft.weaponDetails.activeMode=el.value;autosave();updatePreview();}
function download(doc){const blob=new Blob([JSON.stringify(doc,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${fileSlug(doc.name)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function currentDocument(){return createFoundryItem(state.draft,state.catalog,{existingDocument:state.document});}
function saveItem(){let doc;try{doc=currentDocument();}catch(e){state.step=6;fullRender();toast(e.message,'error');return;}const id=state.id||randomId(24),entry={id,document:doc,updatedAt:new Date().toISOString()};const next=state.collection.filter(i=>i.id!==id);next.unshift(entry);if(!writeStore(KEYS.collection,next)){toast('Não foi possível salvar. Exporte o JSON para guardar seu item.','error');return;}state.collection=next;state.id=id;state.document=doc;state.catalog=extendedCatalog(state.base,doc);autosave();fullRender();toast('Item salvo na sua coleção.');}
function openItem(id,duplicate=false){const item=state.collection.find(i=>i.id===id);if(!item)return;const imported=importItem(item.document,state.base);state.draft=imported.draft;state.document=imported.document;state.catalog=imported.catalog;state.id=duplicate?null:id;if(duplicate)state.draft.name=`${state.draft.name} — cópia`;state.step=duplicate?1:6;state.parts={};state.view='mancer';location.hash='mancer';autosave();fullRender();window.scrollTo({top:0,behavior:'smooth'});}
function resetDraft(){state.draft=newDraft();state.document=null;state.catalog=state.base;state.id=null;state.step=1;state.parts={};state.view='mancer';location.hash='mancer';autosave();fullRender();window.scrollTo({top:0,behavior:'smooth'});}
function exampleDraft(index){const d=newDraft();const findPower=n=>state.base.powers.find(p=>p.name===n)?.uuid;const origin=n=>state.base.origins.find(o=>o.name===n)?.uuid;
 if(index===0){Object.assign(d,{name:'Égide Rubra',description:'Um escudo experimental que converte o impacto em energia. Cada marca em sua superfície conta a história de alguém que ele protegeu.',originUuid:origin('High Tech'),specialPowerIds:['vibranium','returns-when-thrown'],regularPowerUuids:[findPower('Energy Absorption')],restrictions:[{id:'unattached-carried',value:''},{id:'obvious-flashy',value:''}]});}
 if(index===1){Object.assign(d,{name:'Passos de Mercúrio',itemType:'item',description:'Botas de uma liga prateada, construídas para atravessar o impossível. Quando ativadas, deixam no ar um brilho azul que desaparece em segundos.',originUuid:origin('High Tech'),regularPowerUuids:[findPower('Flight 2')],specialPowerIds:['summonable'],restrictions:[{id:'unattached-worn',value:''}]});d.visual={glyph:'bolt',color:'#4f92bc'};d.reliance={type:'tech',affected:'Flight 2'};}
 if(index===2){Object.assign(d,{name:'Coração do Crepúsculo',itemType:'item',description:'Um cristal que pulsa como um segundo coração. Dizem que ele conserva a última promessa de um antigo guardião.',originUuid:origin('Magic'),regularPowerUuids:[findPower('Healing Factor')],specialPowerIds:['bandaging','psychic-link'],restrictions:[{id:'unattached-worn',value:''},{id:'use-once-hour',value:''}]});d.visual={glyph:'gem',color:'#9473b7'};}
 d.regularPowerUuids=d.regularPowerUuids.filter(Boolean);return d;
}
function showExamples(){modal('Uma faísca para a sua ideia.',`<p>Escolha um ponto de partida e personalize tudo. Isso substituirá o rascunho atual.</p><div class="example-options">${[['Égide Rubra','Escudo tecnológico · Vibranium','shield'],['Passos de Mercúrio','Equipamento · Flight 2','bolt'],['Coração do Crepúsculo','Artefato mágico · Healing Factor','gem']].map(([n,s,g],i)=>`<button data-action="example" data-example="${i}">${icon(g)}<span><b>${n}</b><small>${s}</small></span>${icon('arrow')}</button>`).join('')}</div>`);}
async function actions(event){const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='close-modal')$('#modal').close();
 else if(a==='import')$('#import-file').click();
 else if(a==='image')$('#image-file').click();
 else if(a==='new'){if(state.draft.name.trim()||state.draft.regularPowerUuids.length||state.draft.specialPowerIds.length)confirmAction('Começar um novo item?','O rascunho atual será substituído. Itens já salvos continuam na sua coleção.','reset');else resetDraft();}
 else if(a==='reset'){$('#modal').close();resetDraft();}
 else if(a==='next')setStep(state.step+1,true);
 else if(a==='previous')setStep(state.step-1);
 else if(a==='step')setStep(Number(el.dataset.step));
 else if(a==='glyph'){state.draft.visual.glyph=el.dataset.glyph;autosave();fullRender();}
 else if(a==='color'){state.draft.visual.color=el.dataset.color;autosave();fullRender();}
 else if(a==='origin'){state.draft.originUuid=el.dataset.uuid;autosave();fullRender();}
 else if(a==='origin-info'){const o=state.catalog.origins.find(o=>o.uuid===el.dataset.uuid);if(o)modal(o.name,`<p class="description-text">${t(o.description)}</p>${o.examples?`<div class="note"><p><b>Exemplos:</b> ${t(o.examples)}</p></div>`:''}`,button('Escolher esta origem','choose-origin','btn btn-red','check',`data-uuid="${esc(o.uuid)}"`));}
 else if(a==='choose-origin'){state.draft.originUuid=el.dataset.uuid;$('#modal').close();autosave();fullRender();}
 else if(a==='category'){state.filter.category=el.dataset.category;fullRender();}
 else if(a==='remove-restriction')toggleRestriction(el.dataset.id,false);
 else if(a==='power-tab'){state.filter.powerTab=el.dataset.tab;state.filter.power='';state.filter.set='';fullRender();}
 else if(a==='power-info'){const regular=el.dataset.kind==='regular',p=regular?state.catalog.powers.find(p=>p.uuid===el.dataset.id):state.catalog.specials.find(p=>p.id===el.dataset.id);if(p){const s=p.source?.system;modal(nameOf(p),`<div class="power-info-meta"><span>${t(p.powerSet||'Iconic Item')}</span><span>${regular?powerPickCost(p):1} pick(s)</span></div><p class="description-text">${t(regular?p.description:descOf(p))}</p>${s?.effect?`<h3>Efeito</h3><p class="description-text">${t(s.effect)}</p>`:''}${regular?`<dl class="power-facts">${[['Ação',s?.action],['Duração',s?.duration],['Custo',s?.cost],['Alcance',s?.range],['Pré-requisitos',p.prerequisites]].filter(([k,v])=>v).map(([k,v])=>`<div><dt>${k}</dt><dd>${t(v)}</dd></div>`).join('')}</dl>`:''}`);}}
 else if(a==='save')saveItem();
 else if(a==='export'){try{download(currentDocument());toast('JSON preparado para importar no Foundry.');}catch(e){toast(e.message,'error');}}
 else if(a==='print'){if(validateDraft(state.draft,state.catalog).errors.length)return;window.print();}
 else if(a==='open-item')openItem(el.dataset.id);
 else if(a==='duplicate-item')openItem(el.dataset.id,true);
 else if(a==='export-item'){const item=state.collection.find(i=>i.id===el.dataset.id);if(item)download(item.document);}
 else if(a==='delete-item'){const item=state.collection.find(i=>i.id===el.dataset.id);if(item)confirmAction('Excluir este item?',`“${item.document.name}” será removido desta coleção.`,'confirm-delete',`data-id="${esc(item.id)}"`);}
 else if(a==='confirm-delete'){const next=state.collection.filter(i=>i.id!==el.dataset.id);if(!writeStore(KEYS.collection,next)){toast('Não foi possível atualizar a coleção.','error');return;}state.collection=next;if(state.id===el.dataset.id){state.id=null;autosave();}$('#modal').close();fullRender();toast('Item removido da coleção.');}
 else if(a==='go-mancer'){state.view='mancer';location.hash='mancer';fullRender();}
 else if(a==='examples')showExamples();
 else if(a==='example'){state.draft=exampleDraft(Number(el.dataset.example));state.document=null;state.catalog=state.base;state.id=null;state.step=1;state.parts={};state.view='mancer';location.hash='mancer';$('#modal').close();autosave();fullRender();toast('Exemplo carregado. Deixe-o com a sua identidade.');}
}
document.addEventListener('click',event=>{Promise.resolve(actions(event)).catch(e=>toast(e.message||'Não foi possível concluir a ação.','error'));});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.bind)bindField(el);if(el.dataset.restrictionValue){const r=state.draft.restrictions.find(r=>r.id===el.dataset.restrictionValue);if(r){r.value=el.value;autosave();}}if(el.id==='power-search'){state.filter.power=el.value;filterPowers();}if(el.id==='origin-search'){state.filter.origin=el.value;filterOrigins();}if(el.id==='collection-search'){state.filter.collection=el.value;filterCollection();}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.bind){bindField(el);if(['itemType','narratorOverride','reliance.type'].includes(el.dataset.bind))fullRender();}if(el.dataset.restriction)toggleRestriction(el.dataset.restriction,el.checked);if(el.dataset.power)togglePower(el.dataset.power,el.checked);if(el.dataset.special)toggleSpecial(el.dataset.special,el.checked);if(el.dataset.partId){const r=state.draft.restrictions.find(r=>r.id===el.dataset.partId);if(r){const parts=state.parts[r.id]||parseRestrictionParts(r.id,r.value);parts[el.dataset.part]=el.value;state.parts[r.id]=parts;r.value=formatRestrictionParts(r.id,parts);autosave();}}if(el.id==='power-set'){state.filter.set=el.value;filterPowers();}if(el.id==='only-selected'){state.filter.onlySelected=el.checked;filterPowers();}});
$('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>12*1024*1024){toast('O JSON deve ter no máximo 12 MB.','error');return;}try{const imported=importItem(JSON.parse(await file.text()),state.base);const apply=()=>{state.draft=imported.draft;state.document=imported.document;state.catalog=imported.catalog;state.id=null;state.step=6;state.parts={};state.view='mancer';location.hash='mancer';autosave();fullRender();toast('Item importado. Revise ou continue editando.');};if(state.draft.name.trim()){modal('Abrir o item importado?',`<p>“${esc(imported.draft.name)}” substituirá o rascunho atual. Seus itens salvos serão preservados.</p>`,button('Cancelar','close-modal','btn btn-outline')+'<button class="btn btn-red" id="apply-import">Abrir item</button>');$('#apply-import').onclick=()=>{$('#modal').close();apply();};}else apply();}catch(e){toast(e instanceof SyntaxError?'O arquivo não contém um JSON válido.':e.message,'error');}});
$('#image-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>1024*1024||!/^image\/(png|jpeg|webp|gif)$/.test(file.type)){toast('Use uma imagem PNG, JPG, WebP ou GIF de até 1 MB.','error');return;}const reader=new FileReader();reader.onload=()=>{state.draft.image=String(reader.result);autosave();fullRender();};reader.readAsDataURL(file);});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('#modal').close();}});
document.addEventListener('error',event=>{if(event.target.matches?.('[data-preview-image]')){event.target.hidden=true;event.target.nextElementSibling?.classList.add('fallback-art');}},true);
window.addEventListener('hashchange',()=>{state.view=['mancer','colecao','guia'].includes(location.hash.slice(1))?location.hash.slice(1):'mancer';fullRender();});
async function init(){try{const files=await Promise.all(['powers','origins','restrictions','special-powers'].map(async n=>{const r=await fetch(new URL(`./data/${n}.json`,import.meta.url));if(!r.ok)throw new Error(`Não foi possível carregar o catálogo (${r.status}).`);return r.json();}));state.base=makeCatalog(...files);state.catalog=state.base;const saved=readStore(KEYS.draft,null);if(saved?.draft){try{const d=normalizeDraft(saved.draft);const catalog=extendedCatalog(state.base,saved.document);if(d.regularPowerUuids.every(u=>catalog.powers.some(p=>p.uuid===u))&&d.specialPowerIds.every(u=>catalog.specials.some(p=>p.id===u))){state.draft=d;state.document=saved.document||null;state.catalog=catalog;state.step=Math.max(1,Math.min(6,Number(saved.step)||1));state.id=typeof saved.id==='string'?saved.id:null;}}catch{toast('O rascunho anterior não pôde ser recuperado. Seus arquivos exportados podem ser importados.','error');}}const collection=readStore(KEYS.collection,[]);state.collection=Array.isArray(collection)?collection.filter(i=>i?.id&&i.document?.flags?.['iconic-item-mancer']?.isIconicItem):[];state.view=['mancer','colecao','guia'].includes(location.hash.slice(1))?location.hash.slice(1):'mancer';document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));fullRender();}catch(e){$('#main').innerHTML=`<div class="empty-state"><h1>Não foi possível preparar a forja.</h1><p>${esc(e.message)}</p><p>Verifique a conexão e recarregue a página.</p><button class="btn btn-red" id="retry-load">Tentar novamente</button></div>`;$('#retry-load').onclick=init;}}
init();
